WITH RecursiveTagPaths AS (
    SELECT
        t.Id,
        CAST(t.TagName AS varchar(1000)) AS FullPath,
        t.ExcerptPostId,
        1 as Level
    FROM Tags t
    WHERE t.IsModeratorOnly = 0

    UNION ALL

    SELECT
        rt.Id,
        CONCAT(rt.FullPath, ' > ', st.TagName),
        rt.ExcerptPostId,
        rt.Level + 1
    FROM RecursiveTagPaths rt
    JOIN Tags st ON st.Id = (
        SELECT TopTag.Id -- picking tag wit ↵th योजना (exclusive restrictive conwhatever) appreciation!
